use rusqlite::Transaction;
pub(crate) fn apply(t: &Transaction<'_>, c: u32) -> rusqlite::Result<()> { if c < 4 { t.execute_batch("CREATE TABLE IF NOT EXISTS run_checkpoints (run_id TEXT NOT NULL REFERENCES runs(id) ON DELETE CASCADE, checkpoint_id TEXT PRIMARY KEY, stage TEXT NOT NULL, node_id TEXT NOT NULL, attempt INTEGER NOT NULL, input_hash TEXT NOT NULL, state_json BLOB NOT NULL, pending_effects_json BLOB NOT NULL, committed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))); CREATE INDEX IF NOT EXISTS idx_run_checkpoints_run ON run_checkpoints(run_id, committed_at); CREATE TABLE IF NOT EXISTS run_effects (effect_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id) ON DELETE CASCADE, node_id TEXT NOT NULL, kind TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, immutable_intent_hash TEXT NOT NULL, state TEXT NOT NULL, started_at TEXT, completed_at TEXT, result_hash TEXT); CREATE INDEX IF NOT EXISTS idx_run_effects_run ON run_effects(run_id); PRAGMA user_version = 4;")?; } Ok(()) }
